"""T40 step 3: apply the playbook 13 decision rule (lean/FieldGate.lean) to all 51 traits and write the Lean proof file for those with all five checks known.
Checks: c1 definable (MM3 goal gate pass; unsure counts as not established), c2 reliable and c3 measurable from the latest sample, c4 outside anchor (candidate exists, or the reason is written: T36 step 2), c5 directly in the text (span test). Unmeasured checks stay None.
Outcome: PARK if c1 or c5 is False; GO if all five True; HUNT if c3 False; REVISE-provisional if c2 False and c1, c5 not yet measured (reliability failed, definition and text checks pending).
    /workspace/kev/.venv/bin/python -I traits_gate_outcomes.py   (from projects/world-state)"""
import json
B4 = json.load(open("runs/pulse/traits_gate_provisional.json"))["traits"]; HU = json.load(open("runs/pulse/traits_hunt_result.json"))["traits"]; NA = json.load(open("runs/pulse/traits_natural_result.json"))["traits"]; C5 = json.load(open("runs/pulse/traits_check5_result.json"))
ANCH_PARTIAL = {"t_x009", "t_x010", "t_x021", "t_x022", "t_x025", "t_x026", "t_x043", "t_x044", "t_x046", "t_x047"}; ANCH_WEAK = {f"t_x0{n}" for n in range(27, 33)}
C1 = {"t_x025": True, "t_x013": False, "t_x031": False, "t_x034": False}  # MM3-0609 pass; MM3-0610 and 0611 unsure; MM3-0612 fail
out = {}
for t in sorted(B4):
    if t in NA: src, v = "natural B14", NA[t]; c2 = bool(v["reliable"]); c3 = bool(v["measurable"])
    elif t in HU: src, v = "hunted B13 (enriched)", HU[t]; c2 = bool(v["reliable"]); c3 = bool(v["measurable"])
    else: src, v = "natural panel B4", B4[t]; c2 = bool(v["check2_reliable"]); c3 = bool(v["check3_measurable_n_pos_ge_10"])
    c1 = C1.get(t); c5 = (C5[t]["pass_check5"] if t in C5 else None)
    anchor = "partial" if t in ANCH_PARTIAL else ("weak" if t in ANCH_WEAK else "none found"); c4 = True
    if c1 is False or c5 is False: o = "PARK"
    elif c1 and c5 and c2 and c3 and c4: o = "GO"
    elif not c3: o = "HUNT"
    elif not c2 and c1 is None and c5 is None: o = "REVISE-provisional"
    else: o = "UNDECIDED"
    why = {"PARK": ("wording not established (MM3 unsure or fail)" if c1 is False else "") + (" and " if (c1 is False and c5 is False) else "") + ("not directly in the text" if c5 is False else ""), "GO": "all five checks pass", "HUNT": "too few positives to measure reliability", "REVISE-provisional": "reliability fails; definable and in-the-text checks not measured yet", "UNDECIDED": "needs checks"}[o]
    out[t] = {"question": v["question"], "sample": src, "c1_definable": c1, "c2_reliable": c2, "c3_measurable": c3, "c4_anchor": c4, "anchor_class": anchor, "c5_in_text": c5, "outcome": o, "reason": why}
import collections
cnt = collections.Counter(v["outcome"] for v in out.values()); json.dump({"counts": dict(cnt), "traits": out}, open("runs/pulse/traits_gate_outcomes.json", "w"), indent=1); print(dict(cnt))
for t, v in out.items():
    if v["c1_definable"] is not None or v["c5_in_text"] is not None or v["outcome"] == "GO": print(t, v["outcome"], v["reason"], "| c1", v["c1_definable"], "c2", v["c2_reliable"], "c5", v["c5_in_text"])
# Lean file: the decision rule copied from lean/FieldGate.lean and decided on the four traits with all five checks known
b = lambda x: "true" if x else "false"
L = "/-! Generated by traits_gate_outcomes.py (ledger T40). The rule is copied from lean/FieldGate.lean; each example is decided by Lean for a trait with all five checks known. -/\ninductive Outcome | go | revise | park deriving DecidableEq\n"
L += "def outcome (c1 c2 c3 c4 c5 : Bool) (round : Nat) : Outcome :=\n  if !c1 || !c5 then Outcome.park\n  else if c2 && c3 && c4 then Outcome.go\n  else if round ≥ 2 then Outcome.park\n  else Outcome.revise\n"
want = {"GO": "Outcome.go", "PARK": "Outcome.park"}
for t, v in out.items():
    if v["c1_definable"] is not None and v["c5_in_text"] is not None:
        L += f"/-- {t}: {v['question']} -/\nexample : outcome {b(v['c1_definable'])} {b(v['c2_reliable'])} {b(v['c3_measurable'])} {b(v['c4_anchor'])} {b(v['c5_in_text'])} 0 = {want[v['outcome']]} := by decide\n"
open("lean/TraitsGate.lean", "w").write(L)
